CREATE TABLE IF NOT EXISTS src_crm.crm_quotation(id BIGINT AUTO_INCREMENT PRIMARY KEY,quotation_no VARCHAR(32) NOT NULL,version_no INT NOT NULL DEFAULT 1,opportunity_no VARCHAR(32) NOT NULL,customer_code VARCHAR(32) NOT NULL,currency VARCHAR(8) DEFAULT 'CNY',tax_rate DECIMAL(8,4) DEFAULT 13,valid_until DATE,payment_terms VARCHAR(100),total_amount DECIMAL(18,2) DEFAULT 0,total_cost DECIMAL(18,2) DEFAULT 0,discount_rate DECIMAL(8,4) DEFAULT 0,gross_margin_rate DECIMAL(8,4) DEFAULT 0,status VARCHAR(16) DEFAULT 'DRAFT',workflow_instance_id BIGINT,created_by VARCHAR(32),created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),UNIQUE KEY uk_quote_version(quotation_no,version_no),KEY idx_quote_opp(opportunity_no));
CREATE TABLE IF NOT EXISTS src_crm.crm_quotation_line(id BIGINT AUTO_INCREMENT PRIMARY KEY,quotation_id BIGINT NOT NULL,line_no INT NOT NULL,product_code VARCHAR(32) NOT NULL,product_name VARCHAR(200),qty DECIMAL(18,4) NOT NULL,unit_code VARCHAR(16),standard_price DECIMAL(18,4) NOT NULL,sales_price DECIMAL(18,4) NOT NULL,standard_cost DECIMAL(18,4) NOT NULL,line_amount DECIMAL(18,2) NOT NULL,line_cost DECIMAL(18,2) NOT NULL,UNIQUE KEY uk_quote_line(quotation_id,line_no));
